-- repair-enrollment-guard.yml red (2026-11-03, backlog 1263): 66 committed data repairs were never enrolled in
-- ops_repair_guarantee_registry, so its permanent oldest-first rotation could never re-verify them. Enrolled here from each
-- repair's OWN header line. The detector is the one the repair names (or its companion migration shipped beside it) and only
-- when that function exists in production; otherwise NULL — which the registry's own monitor reports as detector_missing, an
-- honest open gap (nothing watches that repair yet) instead of an invisible one. last_verdict starts NULL: the rotation
-- verifies, enrollment does not claim it holds.
insert into public.ops_repair_guarantee_registry (repair_version, repair_name, invariant, detector, registered_by, last_detail)
select v.ver, v.nm, v.inv,
       case when v.det is not null and exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                                                where n.nspname = 'public' and p.proname = v.det) then v.det end,
       'outside engineer 2026-11-03 (backlog 1263): enrolled from the repair''s own header; NULL detector = nothing watches it yet',
       jsonb_build_object('enrolled_by', 'backlog 1263', 'detector_named_by_repair', v.det)
from (values
